<!doctype html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Ultra Premium Options UI - Pro Max</title>
    <style>
        :root {
            /* Default CSS custom properties; values are overridden dynamically by JavaScript at runtime */
            --glass-bg: rgba(150, 150, 150, 0.04);
            --glass-border: rgba(150, 150, 150, 0.12);
            --text-color: inherit;

            /* Global accent palette and named easing curves shared across all animated elements */
            --accent-primary: #d4af37;
            --accent-glow: rgba(212, 175, 55, 0.15);
            --accent-border: rgba(212, 175, 55, 0.4);
            --spring-curve: cubic-bezier(0.175, 0.885, 0.32, 1.275);
            --smooth-curve: cubic-bezier(0.16, 1, 0.3, 1);
        }

        /* Dark theme variant: pure-white text with luminous glass-border highlights */
        .theme-dark {
            --text-color: #ffffff;
            --glass-bg: rgba(255, 255, 255, 0.06);
            --glass-border: rgba(255, 255, 255, 0.15);
        }

        /* Light theme variant: near-black text with softened translucent surface depth */
        .theme-light {
            --text-color: #1a1a1a;
            --glass-bg: rgba(0, 0, 0, 0.03);
            --glass-border: rgba(0, 0, 0, 0.1);
        }

        body {
            font-family: system-ui, -apple-system, 'SF Pro Display', 'Segoe UI', Roboto, sans-serif;
            margin: 0;
            padding: 8px 0;
            background-color: transparent;
            display: flex;
            flex-direction: column;
            align-items: center;
            width: 100%;
        }

        .action-wrapper {
            width: 100%;
            max-width: 720px;
            box-sizing: border-box;
            padding: 0 4px;
            display: flex;
            flex-direction: column;
            gap: 10px;
            transition: all 0.4s var(--smooth-curve); /* Smooth cross-fade transition applied on every theme switch */
        }

        /* Top control bar housing the theme-color toggle and interaction-mode toggle buttons */
        .controls-bar {
            display: flex;
            justify-content: flex-end;
            gap: 8px; /* Horizontal gap between the two control buttons */
