             * persisted in localStorage under the key "era_options_text_theme".
             * ============================================================== */
            const themeBtn = document.getElementById('theme-toggle-btn');
            const themeIconContainer = document.getElementById('theme-icon-container');

            // Initialize from persisted storage; falls back to "light" when no value is stored
            let currentTheme = localStorage.getItem('era_options_text_theme') || 'light';

            function updateThemeUI() {
                if (currentTheme === 'dark') {
                    // Moon icon signals the dark theme; card text transitions to pure white
                    themeIconContainer.innerHTML = icons.moon;
                    wrapper.classList.remove('theme-light');
                    wrapper.classList.add('theme-dark');
                } else {
